int main(){try{const auto directory=fs::temp_directory_path()/("ark-frame-sheet-operations-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));check(fs::create_directory(directory),"private output directory created");frame(directory);frameProfiles();frameNoBeadDensity();sheet(directory);sheetCalibration();std::cout<<"frame endpoint, weld and sheet forming tests passed\n";return 0;}catch(const std::exception& error){std::cerr<<"FAIL: "<<error.what()<<'\n';return 1;}}
